#include "stdafx.h"#include "ControlBuilderE.h"#include "./../../HoneyWell/Include/StateSer.h"static LPCSTR s_szW = "W";int KControlBuilderE::SaveState(){  ver = GetLastVersion();  S_CLASS( (char*)s_szW,_W);  KStateSer saver;  return KControlBuilder::SaveState( saver.GetInterface() );}int KControlBuilderE::RestoreState( char * StrName ){  if( strcmp( StrName, s_szW ) )    return 1;  bool r = pSRFile->RStruct( sizeof ( _W ), static_cast<_W*>(this) );  ASS( r );  if( !r )    return 2;  ASS( ver==GetLastVersion() );  if( ver!=GetLastVersion() )    return -1;  KStateSer rest;  return KControlBuilder::RestoreState( rest.GetInterface() );}